using ModelContextProtocol.Server;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddMcpServer(options =>
{
    options.ServerInfo = new()
    {
        Name = "MyConfigServer",
        Version = "1.0.0",
    };
})
.WithHttpTransport()
.WithTools<MyTools>()
.WithResources<MyResources>();

var app = builder.Build();

app.MapMcp();

app.Run();

// --- Tools ---

[McpServerToolType]
public static class MyTools
{
    [McpServerTool(Name = "greet", Title = "Greet a user")]
    public static string Greet(string name) =>
        $"Hello, {name}! Welcome to the MCP server.";

    [McpServerTool(Name = "add", Title = "Add two numbers")]
    public static string Add(double a, double b) =>
        $"Result: {a + b}";
}

// --- Resources ---

[McpServerResourceType]
public static class MyResources
{
    [McpServerResource(
        Name = "config",
        UriTemplate = "config://app/settings",
        MimeType = "application/json")]
    public static string GetAppConfig() =>
        """
        {
          "appName": "MyConfigServer",
          "version": "1.0.0",
          "features": {
            "enableLogging": true,
            "maxRetries": 3,
            "timeoutSeconds": 30
          }
        }
        """;

    [McpServerResource(
        Name = "status",
        UriTemplate = "config://app/status",
        MimeType = "application/json")]
    public static string GetAppStatus() =>
        """
        {
          "status": "healthy",
          "uptime": "running"
        }
        """;
}

